const raw = $input.first().json;
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const missing = [];
if (!body.device_id)  missing.push('device_id');
if (!body.event_type) missing.push('event_type');
if (missing.length > 0) {
  return [{ json: { valid: false, error: `Thiếu trường bắt buộc: ${missing.join(', ')}` } }];
}
const amount = body.payload?.amount || 0;
const d = {
  valid: true,
  device_id:  String(body.device_id),
  event_type: String(body.event_type),
  payload:    body.payload || {},
  amount_vnd: amount,
  amount_fmt: new Intl.NumberFormat('vi-VN').format(amount) + ' VND'
};
d.request_body = JSON.stringify({ device_id: d.device_id, event_type: d.event_type, payload: d.payload });
return [{ json: d }];

const dbResult = $input.first().json;
const orig = $('Kiểm tra và làm giàu dữ liệu').first().json;
const d = { ...orig, db_id: dbResult.id, created_at: dbResult.created_at, db_ok: true };
const isInvoice = ['sale_completed', 'payment_received', 'invoice'].includes(d.event_type);
d.discord_body = JSON.stringify({
  embeds: [{
    title: (isInvoice ? 'Hóa đơn mới' : 'Sự kiện POS') + ' — ' + d.device_id,
    color: isInvoice ? 52307 : 16744448,
    fields: [
      { name: 'Thiết bị',  value: d.device_id,             inline: true  },
      { name: 'Loại',      value: d.event_type,            inline: true  },
      { name: 'DB Record', value: '#' + (d.db_id || '?'),  inline: true  },
      { name: 'Số tiền',   value: d.amount_fmt || 'N/A',   inline: true  },
      { name: 'Thời gian', value: d.created_at || new Date().toISOString(), inline: false }
    ],
    footer: { text: 'n8n IoT Pipeline • NeonDB' }
  }]
});
d.response_201 = JSON.stringify({ status: 'ok', id: d.db_id, device: d.device_id, event: d.event_type, timestamp: d.created_at });
return [{ json: d }];
